from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Base 9-point Gauss–Seidel stencil.
@proc
def kernel_seidel_2d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # Need at least one interior point.
    assert n > 2

    # Time stepping.
    for t in seq(0, tsteps):
        # Spatial sweep: in-place Gauss–Seidel update.
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                # Accumulate the 3x3 neighborhood in a scalar to keep it in a register.
                s: DATA_TYPE
                s = (
                    A[i - 1, j - 1] + A[i - 1, j] + A[i - 1, j + 1]
                    + A[i,     j - 1] + A[i,     j] + A[i,     j + 1]
                    + A[i + 1, j - 1] + A[i + 1, j] + A[i + 1, j + 1]
                )
                A[i, j] = s / 9.0


