# I_TILE is a compile-time tuning parameter; 32 is a reasonable default
# for modern x86 L1 data caches.
I_TILE = 32
p = divide_loop(p, p.find_loop("i"), I_TILE, ["io", "ii"], tail="cut_and_guard")

# Clean up expressions introduced by loop transformations.
p = simplify(p)

# Expose the optimized kernel under the name expected by the C driver.
kernel_seidel_2d = p
