/* Kernel implementation in Exo:

   This Exo code defines a straightforward Gauss–Seidel 2D stencil and then
   applies a small schedule:
     - shift the inner j-loop to start at 0, to simplify strip-mining;
     - strip-mine (divide) the j-loop into blocks of size 4;
     - fully unroll the inner 4-iteration loop to improve ILP and enable
       auto-vectorization;
     - simplify the resulting index arithmetic;
     - finally, expose the scheduled version under the name
       `kernel_seidel_2d`, which is what the C driver calls.

   All loop transformations preserve the original (t, i, j) lexicographic
   order, so the Gauss–Seidel dependence pattern (each point using updated
   left / upper neighbors and old right / lower neighbors within a time
   step) is preserved exactly.
EXO START
from __future__ import annotations

# Core Exo constructs.
from exo import *

# Scheduling primitives (required by the problem statement).
from exo.API_scheduling import *

# Standard DRAM memory.
from exo.libs.memories import DRAM

# Optional higher-level scheduling utilities (not used directly here,
# but imported per guidelines and for potential future tuning).
from exo.stdlib.stdlib import vectorize, tile_loops


@proc
def kernel_seidel_2d_base(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # The kernel operates on the interior of the n x n grid, so we
    # require at least one interior point in each dimension.
    assert n > 2

    # Precompute 1/9 once and then use a multiplication in the hot loop
    # instead of a division per grid point.
    one_ninth: DATA_TYPE
    one_ninth = 1.0 / 9.0

    for t in seq(0, tsteps):
        # Standard Gauss–Seidel traversal:
        #   - i increases from 1 to n-2
        #   - j increases from 1 to n-2
        # Each update uses:
        #   * already-updated values from row i-1 and column j-1
        #   * not-yet-updated values from row i+1 and column j+1
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                A[i, j] = (
                    A[i - 1, j - 1] + A[i - 1, j] + A[i - 1, j + 1]
                    + A[i,     j - 1] + A[i,     j] + A[i,     j + 1]
                    + A[i + 1, j - 1] + A[i + 1, j] + A[i + 1, j + 1]
                ) * one_ninth


# --------------------------------------------------------------------
# Scheduling for performance
# --------------------------------------------------------------------
# We now apply a sequence of semantics-preserving transformations to
# `kernel_seidel_2d_base` to obtain an optimized version:
#
# 1. Shift the inner j-loop to start at 0 (instead of 1). This simplifies
#    subsequent strip-mining and does not change which array elements are
#    updated, only how the loop index is written.
#
# 2. Strip-mine (divide) the j-loop into an outer "block" loop and an
#    inner loop of constant size 4. The overall (t, i, j) execution order
#    is identical to the original lexicographic order, so Gauss–Seidel
#    dependencies remain unchanged.
#
# 3. Fully unroll the inner 4-iteration loop to increase instruction-level
#    parallelism and to make it easier for the backend C compiler to
#    vectorize the stencil in the j dimension.
#
# 4. Simplify the resulting index arithmetic.
#
# 5. Rename the final scheduled procedure to `kernel_seidel_2d`, which is
#    the name used by the C driver.
p = kernel_seidel_2d_base

# 1) Shift the inner j-loop to start at 0 instead of 1.
#    Original: for j in seq(1, n - 1):
#    After shift: for j in seq(0, n - 2):
#      and every occurrence of `j` in the body is replaced by `j + 1`.
p = shift_loop(p, "j", "0")

# 2) Strip-mine (divide) the j-loop into blocks of size 4.
#    This yields something conceptually like:
#      for j_outer in ...:
#          for j_inner in seq(0, 4):
#              ... use j = 4*j_outer + j_inner ...
#      # plus a short tail loop for the remaining elements
J_BLOCK = 4
p = divide_loop(p, "j", J_BLOCK, ("jo", "ji"), tail="cut")

# 3) Fully unroll the small inner 'ji' loop (constant bound: 4).
#    We apply unrolling to every `ji` loop instance.
for c in p.find_all("for ji in _:_"):
    p = unroll_loop(p, c)

# 4) Simplify the index arithmetic that was introduced by the
#    shift/divide/unroll steps.
p = simplify(p)

# 5) Expose the scheduled kernel under the name expected by the C driver.
kernel_seidel_2d = rename(p, "kernel_seidel_2d")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_seidel_2d(/*ctxt=*/NULL, tsteps, n,
                   (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
