from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Base Gauss-Seidel 2D kernel: exactly matches the original PolyBench
# seidel-2d computation (9-point stencil, in-place updates).
@proc
def kernel_seidel_2d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # We only update interior points [1 .. n-2] in both dimensions.
    assert n > 2

    for t in seq(0, tsteps):
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                # 9-point stencil average:
                # uses already-updated values above and to the left,
                # and previous-step values below and to the right.
                A[i, j] = (
                    A[i - 1, j - 1] + A[i - 1, j] + A[i - 1, j + 1]
                    + A[i,     j - 1] + A[i,     j] + A[i,     j + 1]
                    + A[i + 1, j - 1] + A[i + 1, j] + A[i + 1, j + 1]
                ) / 9.0

# --------------------------------------------------------------------
# Scheduling / optimization
# --------------------------------------------------------------------
# We apply only dependence-preserving transformations. In particular:
#  - We do NOT reorder the i and j loops, to keep the Gauss-Seidel
#    update order identical to the original code.
#  - We split (tile) the innermost j loop to improve cache behavior
#    and expose a fixed-size inner loop that we can safely unroll.
#
# The iteration order of (i, j) within each time step is preserved,
# so all data dependencies (up, left, and up-diagonals) are unchanged.

p = kernel_seidel_2d

# Tile factor for the inner j loop. This is a small constant chosen
# to balance code size and unrolling benefits. It can be tuned for
# different machines if desired.
